 for(const y of streetsY){ctx.fillStyle='#555a52';ctx.fillRect(0,y-WORLD.road/2,WORLD.w,WORLD.road);ctx.fillStyle='#424942';ctx.fillRect(0,y-WORLD.road/2+6,WORLD.w,2);ctx.fillRect(0,y+WORLD.road/2-8,WORLD.w,2);ctx.fillStyle='#aaa58a';for(let x=15;x<WORLD.w;x+=54)ctx.fillRect(x,y-2,26,4);ctx.fillStyle='#e7e1c8';for(let x=0;x<WORLD.w;x+=400){for(let q=-2;q<=2;q++)ctx.fillRect(x-59,y+q*10-3,25,6)}}
 // sidewalk corner markings and parking bays
 for(const x of streetsX)for(const y of streetsY){ctx.fillStyle='#e4ddc4';for(let q=-2;q<=2;q++){ctx.fillRect(x+q*11-3,y-61,6,26);ctx.fillRect(x+q*11-3,y+35,6,26);ctx.fillRect(x-61,y+q*11-3,26,6);ctx.fillRect(x+35,y+q*11-3,26,6)}}
 // buildings
 for(const b of buildings){ctx.fillStyle='#161d19';ctx.fillRect(b.x+9,b.y+11,b.w,b.h);ctx.fillStyle='#657064';ctx.fillRect(b.x-5,b.y-5,b.w+10,b.h+10);ctx.fillStyle=b.color;ctx.fillRect(b.x,b.y,b.w,b.h);ctx.fillStyle='#505a50';ctx.fillRect(b.x+5,b.y+5,b.w-10,8);ctx.fillStyle='#27322d';ctx.fillRect(b.x+12,b.y+14,b.w-24,b.h-28);
  let floors=2+Math.floor(rand(b.seed+2)*3),rows=4+Math.floor(rand(b.seed+5)*3);for(let f=0;f<floors;f++)for(let r=0;r<rows;r++){let xx=b.x+20+r*(b.w-43)/Math.max(1,rows-1),yy=b.y+25+f*(b.h-50)/floors;ctx.fillStyle=(rand(b.seed+f*7+r*3)>.45)?'#d5a35b':'#53625a';ctx.globalAlpha=.6;ctx.fillRect(xx,yy,7,9);ctx.globalAlpha=1}
  ctx.fillStyle='#d5cc9b';ctx.fillRect(b.x+b.w/2-16,b.y+b.h-15,32,8);if(b.roof){ctx.fillStyle='#667267';ctx.fillRect(b.x+b.w*.63,b.y+b.h*.4,33,23);ctx.fillStyle='#83836b';ctx.fillRect(b.x+25,b.y+36,42,19)} }
 // street clutter / palms
 for(let i=0;i<72;i++){let x=rand(i+90)*WORLD.w,y=rand(i+170)*WORLD.h;if(!onRoad(x,y)&&!buildings.some(b=>x>b.x-12&&x<b.x+b.w+12&&y>b.y-12&&y<b.y+b.h+12))drawTree(x,y)}
 // target beacon
 if(mission<4){let goal=goals[Math.min(mission===2?2:mission,2)];if(mission===1)goal=goals[1];if(mission===2)goal=goals[2];if(!(mission===1&&player.car)){let pulse=(Date.now()%1200)/1200;ctx.strokeStyle='#d7ff48';ctx.lineWidth=3;ctx.globalAlpha=.85;ctx.beginPath();ctx.arc(goal.x,goal.y,20+pulse*24,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1;ctx.fillStyle='#d7ff48';ctx.beginPath();ctx.arc(goal.x,goal.y,6,0,Math.PI*2);ctx.fill();ctx.font='bold 14px Barlow Condensed';ctx.fillText(goal.label,goal.x+16,goal.y-16)}}
 // cars
 for(const c of cars)drawCar(c);if(player.car){}else drawPlayer(p.x,p.y,p.angle);
 // fake police pursuit - spawn cars toward player
 if(wanted>0){for(let i=0;i<wanted;i++){let a=Date.now()/1400+i*2.7,dist=300+i*90;let cx=clamp(p.x+Math.cos(a)*dist,30,WORLD.w-30),cy=clamp(p.y+Math.sin(a)*dist,30,WORLD.h-30);if(!onRoad(cx,cy)){let nx=streetsX.reduce((best,x)=>Math.abs(x-cx)<Math.abs(best-cx)?x:best,streetsX[0]);let ny=streetsY.reduce((best,y)=>Math.abs(y-cy)<Math.abs(best-cy)?y:best,streetsY[0]);if(Math.abs(nx-cx)<Math.abs(ny-cy))cx=nx;else cy=ny}drawCar({x:cx,y:cy,angle:Math.atan2(p.y-cy,p.x-cx),color:'#d9ddd5',police:true})}}
 ctx.restore();drawVignette();drawMap(camX,camY);ctx.restore();}
function drawTree(x,y){ctx.fillStyle='#6b6045';ctx.fillRect(x-2,y-2,4,8);ctx.fillStyle='#41603d';ctx.beginPath();ctx.arc(x,y-5,10,0,Math.PI*2);ctx.fill();ctx.fillStyle='#567548';ctx.beginPath();ctx.arc(x-4,y-8,5,0,Math.PI*2);ctx.fill()}
function drawCar(c){ctx.save();ctx.translate(c.x,c.y);ctx.rotate(c.angle);ctx.fillStyle='#111';ctx.fillRect(-18,-11,36,23);ctx.fillStyle=c.color;ctx.fillRect(-16,-9,32,18);ctx.fillStyle='#232c2a';ctx.fillRect(-5,-8,12,16);ctx.fillStyle='#84918a';ctx.fillRect(-4,-7,9,14);ctx.fillStyle='#ffedaf';ctx.fillRect(13,-7,3,4);ctx.fillRect(13,3,3,4);ctx.fillStyle='#d8504d';ctx.fillRect(-16,-7,2,4);ctx.fillRect(-16,3,2,4);ctx.fillStyle='#171916';ctx.fillRect(-12,-12,7,2);ctx.fillRect(6,-12,7,2);ctx.fillRect(-12,10,7,2);ctx.fillRect(6,10,7,2);if(c.police){ctx.fillStyle='#426cf5';ctx.fillRect(-3,-8,5,3);ctx.fillStyle='#fc454a';ctx.fillRect(2,-8,5,3);ctx.globalAlpha=.19;ctx.fillStyle='#ff4343';ctx.beginPath();ctx.arc(4,0,26,0,Math.PI*2);ctx.fill()}ctx.restore()}
function drawPlayer(x,y,a){ctx.save();ctx.translate(x,y);ctx.rotate(a);ctx.fillStyle='#141817';ctx.beginPath();ctx.ellipse(0,3,9,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d7ff48';ctx.fillRect(-5,-7,10,13);ctx.fillStyle='#f0c39a';ctx.beginPath();ctx.arc(2,-8,4,0,Math.PI*2);ctx.fill();ctx.restore()}
function drawVignette(){let g=ctx.createRadialGradient(W/2,H/2,Math.min(W,H)*.25,W/2,H/2,Math.max(W,H)*.75);g.addColorStop(0,'#00000000');g.addColorStop(1,'#070a08b5');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.fillStyle='#d7ff4812';ctx.fillRect(0,0,W,H)}
function drawMap(camX,camY){let w=mapCanvas.clientWidth,h=mapCanvas.clientHeight;mctx.clearRect(0,0,w,h);mctx.fillStyle='#17211a';mctx.fillRect(0,0,w,h);let sx=w/WORLD.w,sy=h/WORLD.h;mctx.fillStyle='#545c50';for(let x of streetsX)mctx.fillRect((x-WORLD.road/2)*sx,0,WORLD.road*sx,h);for(let y of streetsY)mctx.fillRect(0,(y-WORLD.road/2)*sy,w,WORLD.road*sy);mctx.fillStyle='#56674b';for(let a of parks)mctx.fillRect(a.x*sx,a.y*sy,a.w*sx,a.h*sy);mctx.fillStyle='#38443d';for(let b of buildings)mctx.fillRect(b.x*sx,b.y*sy,b.w*sx,b.h*sy);if(mission<4){let g=goals[mission===1?1:mission===2?2:0];mctx.fillStyle='#d7ff48';mctx.beginPath();mctx.arc(g.x*sx,g.y*sy,3.5,0,Math.PI*2);mctx.fill()}mctx.fillStyle='#fff';mctx.beginPath();mctx.arc(p.x*sx,p.y*sy,3,0,Math.PI*2);mctx.fill();mctx.strokeStyle='#d7ff48';mctx.lineWidth=1;mctx.stroke();}
let last=performance.now();function loop(now){let dt=(now-last)/1000;last=now;update(dt);draw();requestAnimationFrame(loop)}updateMission();syncHud();requestAnimationFrame(loop);
})();
