for(let i=0;i<72;i++){let x=rand(i+90)*WORLD.w,y=rand(i+170)*WORLD.h;if(!onRoad(x,y)&&!buildings.some(b=>x>b.x-12&&x<b.x+b.w+12&&y>b.y-12&&y<b.y+b.h+12))drawTree(x,y)}
if(mission<4){let goal=goals[mission===1?1:mission===2?2:0];if(!(mission===1&&player.car)){let pulse=(Date.now()%1200)/1200;ctx.strokeStyle='#d7ff48';ctx.lineWidth=3;ctx.globalAlpha=.85;ctx.beginPath();ctx.arc(goal.x,goal.y,20+pulse*24,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1;ctx.fillStyle='#d7ff48';ctx.beginPath();ctx.arc(goal.x,goal.y,6,0,Math.PI*2);ctx.fill();ctx.font='bold 14px Barlow Condensed';ctx.fillText(goal.label,goal.x+16,goal.y-16)}}for(const c of cars)drawCar(c);if(!player.car)drawPlayer(p.x,p.y,p.angle);
if(wanted>0)for(let i=0;i<wanted;i++){let a=Date.now()/1400+i*2.7,dist=300+i*90,cx=clamp(p.x+Math.cos(a)*dist,30,WORLD.w-30),cy=clamp(p.y+Math.sin(a)*dist,30,WORLD.h-30);if(!onRoad(cx,cy)){let nx=streetsX.reduce((best,x)=>Math.abs(x-cx)<Math.abs(best-cx)?x:best,streetsX[0]),ny=streetsY.reduce((best,y)=>Math.abs(y-cy)<Math.abs(best-cy)?y:best,streetsY[0]);if(Math.abs(nx-cx)<Math.abs(ny-cy))cx=nx;else cy=ny}drawCar({x:cx,y:cy,angle:Math.atan2(p.y-cy,p.x-cx),color:'#d9ddd5',police:true})}ctx.restore();drawVignette();drawMap();ctx.restore()}
