 const player={x:250,y:180,angle:0,speed:0,car:null,health:100},cars=[],carColors=['#cf5549','#e2bd58','#5886a0','#ddd7c3','#73896b','#a55b87','#d7803c'];let cash=2450,wanted=0,heat=0,started=false,mission=0,toastTimer=0,shake=0;for(let i=0;i<34;i++){let horizontal=i%2===0,road=horizontal?streetsY[(i*3)%5]:streetsX[(i*7)%6],pos=rand(i+9)*(horizontal?WORLD.w:WORLD.h);cars.push({x:horizontal?pos:road+(rand(i)*32-16),y:horizontal?road+(rand(i)*32-16):pos,angle:horizontal?(rand(i+3)>.5?0:Math.PI):(rand(i+3)>.5?Math.PI/2:-Math.PI/2),color:carColors[i%carColors.length],speed:0,ai:1.2+rand(i+4)*.8,parked:i%3===0,police:false})}function onRoad(x,y){return streetsX.some(a=>Math.abs(x-a)<WORLD.road/2)||streetsY.some(a=>Math.abs(y-a)<WORLD.road/2)}const goals=[{x:1010,y:820,label:'THE CYPRESS STASH'},{x:1780,y:1180,label:'THE GETAWAY'},{x:230,y:1500,label:'THE DROP'}];function notify(msg){let el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');toastTimer=2.2}function updateMission(){let t=document.querySelector('#missionTitle'),p=document.querySelector('#missionText');if(mission===0){t.textContent='A LITTLE PICKUP';p.textContent='Find the marked stash in the Cypress district. Keep it quiet, keep it moving.'}else if(mission===1){t.textContent='BORROWED WHEELS';p.textContent='Get to the getaway car. The heat is on — lose the cops before the drop.'}else if(mission===2){t.textContent='LOSE THE HEAT';p.textContent='Stay out of the police search zone until the heat cools, then head to the drop.'}else{t.textContent='CLEAN GETAWAY';p.textContent='You made it through the night. Cruise the city, or hit the streets for another score.'}}
 const keys={};addEventListener('keydown',e=>{let k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='e'&&started)toggleCar();if(k==='enter'&&!started)begin()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);document.querySelector('#play').onclick=begin;function begin(){if(started)return;started=true;document.querySelector('#start').style.opacity=0;setTimeout(()=>document.querySelector('#start').style.display='none',500);notify('NIGHT RUN STARTED')}function toggleCar(){if(player.car){player.x=player.car.x+Math.cos(player.car.angle+Math.PI/2)*34;player.y=player.car.y+Math.sin(player.car.angle+Math.PI/2)*34;player.car.occupied=false;player.car=null;player.speed=0;notify('ON FOOT')}else{let near=null,dist=58;for(const c of cars){let d=Math.hypot(c.x-player.x,c.y-player.y);if(d<dist){near=c;dist=d}}if(near){player.car=near;near.occupied=true;near.parked=false;player.angle=near.angle;notify('NICE RIDE')}else notify('NO CAR IN REACH')}}for(const b of document.querySelectorAll('.pad button')){let key={up:'w',down:'s',left:'a',right:'d'}[b.dataset.k];b.onpointerdown=e=>{e.preventDefault();keys[key]=true};for(const ev of ['pointerup','pointercancel','pointerleave'])b.addEventListener(ev,()=>keys[key]=false)}document.querySelector('[data-action=enter]').onpointerdown=e=>{e.preventDefault();if(started)toggleCar()};document.querySelector('[data-action=boost]').onpointerdown=e=>{e.preventDefault();keys.shift=true};document.querySelector('[data-action=boost]').onpointerup=()=>keys.shift=false;
